int parse_fmtp_config_h264(AVFormatContext *s, AVStream *stream, PayloadContext *h264_data, const char *attr, const char *value) {
    if (!strcmp(attr, "packetization-mode")) {
        int mode = atoi(value);
        av_log(s, AV_LOG_DEBUG, "packetization-mode: %d\n", mode);
        if (mode != 0 && mode != 1) {
            av_log(s, AV_LOG_ERROR, "packetization-mode %d not supported\n", mode);
            return AVERROR(EINVAL);
        }
    } else if (!strcmp(attr, "profile-level-id")) {
        if (strlen(value) != 6) {
            av_log(s, AV_LOG_ERROR, "Invalid profile-level-id length\n");
            return AVERROR(EINVAL);
        }
        memcpy(h264_data->profile_level_id, value, 6);
    } else if (!strcmp(attr, "sprop-parameter-sets")) {
        int i, ret;
        uint8_t *p;
        char *sprop, *sprop_end;
        AVCodecParameters *par = stream->codecpar;

        if (!value || !value[0]) {
            av_log(s, AV_LOG_ERROR, "Invalid sprop-parameter-sets value\n");
            return AVERROR(EINVAL);
        }
        if (par->extradata) {
            av_freep(&par->extradata);
            par->extradata_size = 0;
        }

        sprop = av_strdup(value);
        if (!sprop)
            return AVERROR(ENOMEM);

        sprop_end = sprop + strlen(sprop);
        for (i = 0; sprop < sprop_end && i < 2; i++) {
            char *p1, *p2;
            int size;
            unsigned char *buf;

            if (*sprop == ',')
                sprop++;
            else if (!i)
                break;
            p1 = sprop;
            while (sprop < sprop_end && *sprop != ',') {
                if (*sprop == ';') {
                    av_log(s, AV_LOG_ERROR, "Invalid sprop-parameter-sets format\n");
                    ret = AVERROR(EINVAL);
                    goto end;
                }
                sprop++;
            }
            if (sprop >= sprop_end)
                break;
            p2 = sprop;
            size = av_base64_decode(NULL, 0, p1, p2 - p1);
            if (size < 0) {
                av_log(s, AV_LOG_ERROR, "Invalid base64 parameter set\n");
                ret = AVERROR(EINVAL);
                goto end;
            }
            buf = av_malloc(size + 1);
            if (!buf) {
                ret = AVERROR(ENOMEM);
                goto end;
            }
            av_base64_decode(buf, size + 1, p1, p2 - p1);
            if (par->extradata_size + size + 1 > par->extradata_size) {
                uint8_t *new_extradata = av_malloc(par->extradata_size + size + 1);
                if (!new_extradata) {
                    av_freep(&buf);
                    ret = AVERROR(ENOMEM);
                    goto end;
                }
                memcpy(new_extradata, par->extradata, par->extradata_size);
                av_freep(&par->extradata);
                par->extradata = new_extradata;
                par->extradata_size += size + 1;
            }
            memcpy(par->extradata + par->extradata_size - size - 1 + i, buf, size);
            av_free(buf);
        }
        if (i < 2)
            av_log(s, AV_LOG_DEBUG, "Incomplete parameter sets\n");
        ret = 0;
    end:
        av_free(sprop);
        if (ret < 0)
            return ret;
    } else {
        av_log(s, AV_LOG_DEBUG, "Ignoring unsupported FMTP attribute '%s'\n", attr);
    }
    return 0;
}

int parse_fmtp_config_h264(AVFormatContext *s, AVStream *stream, PayloadContext *h264_data, const char *attr, const char *value) {
    if (!strcmp(attr, "packetization-mode")) {
        int mode = atoi(value);
        av_log(s, AV_LOG_DEBUG, "packetization-mode: %d\n", mode);
        if (mode != 0 && mode != 1) {
            av_log(s, AV_LOG_ERROR, "packetization-mode %d not supported\n", mode);
            return AVERROR(EINVAL);
        }
    } else if (!strcmp(attr, "profile-level-id")) {
        if (strlen(value) != 6) {
            av_log(s, AV_LOG_ERROR, "Invalid profile-level-id\n");
            return AVERROR(EINVAL);
        }
        av_strlcpy(h264_data->profile_level_id, value, sizeof(h264_data->profile_level_id));
    } else if (!strcmp(attr, "sprop-parameter-sets")) {
        char *p, *q;
        int i = 0;
        char *sets[2];

        av_freep(&h264_data->extradata);
        h264_data->extradata_size = 0;

        p = av_strdup(value);
        if (!p)
            return AVERROR(ENOMEM);

        q = p;
        while (*q && i < 2) {
            if (*q == ',') {
                *q++ = 0;
                while (*q && *q == ' ')
                    q++;
                if (*q)
                    sets[i++] = q;
            } else {
                q++;
            }
        }
        if (i == 2) {
            uint8_t *buf = NULL;
            int size = 0;
            for (i = 0; i < 2; i++) {
                int len = strlen(sets[i]);
                if (len < 2) {
                    av_log(s, AV_LOG_ERROR, "Invalid sprop-parameter-sets\n");
                    av_free(p);
                    return AVERROR(EINVAL);
                }
                int v_len = av_base64_decode(NULL, 0, sets[i]);
                if (v_len < 0) {
                    av_log(s, AV_LOG_ERROR, "Invalid sprop-parameter-sets\n");
                    av_free(p);
                    return AVERROR(EINVAL);
                }
                buf = av_malloc(size + v_len + 1);
                if (!buf) {
                    av_free(p);
                    return AVERROR(ENOMEM);
                }
                if (size)
                    memcpy(buf, h264_data->extradata, size);
                av_base64_decode(buf + size, v_len, sets[i]);
                size += v_len;
                av_freep(&h264_data->extradata);
                h264_data->extradata = buf;
            }
            h264_data->extradata_size = size;
        }
        av_free(p);
    }

    return 0;
}

int parse_fmtp_config_h264(AVFormatContext *s, AVStream *stream, PayloadContext *h264_data, const char *attr, const char *value) {
    if (!strcmp(attr, "packetization-mode")) {
        int mode = atoi(value);
        av_log(s, AV_LOG_DEBUG, "packetization-mode: %d\n", mode);
        if (mode != 0 && mode != 1) {
            av_log(s, AV_LOG_ERROR, "packetization-mode %d is not supported\n", mode);
            return AVERROR(EINVAL);
        }
        h264_data->packetization_mode = mode;
    } else if (!strcmp(attr, "profile-level-id")) {
        if (strlen(value) != 6) {
            av_log(s, AV_LOG_ERROR, "Invalid profile-level-id\n");
            return AVERROR(EINVAL);
        }
        h264_data->profile_level_id[0] = value[0];
        h264_data->profile_level_id[1] = value[1];
        h264_data->profile_level_id[2] = value[2];
        h264_data->profile_level_id[3] = value[3];
        h264_data->profile_level_id[4] = value[4];
        h264_data->profile_level_id[5] = value[5];
    } else if (!strcmp(attr, "sprop-parameter-sets")) {
        char *p, *sprop, *p1, *p2;
        int i, len, ret;

        sprop = av_strdup(value);
        if (!sprop)
            return AVERROR(ENOMEM);

        p1 = sprop;
        p2 = strchr(p1, ',');
        if (!p2) {
            av_freep(&sprop);
            return AVERROR(EINVAL);
        }
        *p2 = 0;
        p2++;
        p = strchr(p1, ';');
        if (p)
            *p = 0;

        len = strlen(p1);
        h264_data->extradata = av_malloc(len + 1);
        if (!h264_data->extradata) {
            av_freep(&sprop);
            return AVERROR(ENOMEM);
        }
        h264_data->extradata_size = len;

        for (i = 0; i < len; i += 4) {
            int v;
            if (i + 3 >= len) {
                av_log(s, AV_LOG_ERROR, "Invalid sprop-parameter-sets\n");
                av_freep(&sprop);
                return AVERROR(EINVAL);
            }
            v = h264_data->extradata[i + 0] << 24;
            v |= h264_data->extradata[i + 1] << 16;
            v |= h264_data->extradata[i + 2] << 8;
            v |= h264_data->extradata[i + 3];
            h264_data->extradata[i / 4] = v;
        }

        len = strlen(p2);
        h264_data->extradata = av_realloc(h264_data->extradata, h264_data->extradata_size + len + 1);
        if (!h264_data->extradata) {
            av_freep(&sprop);
            return AVERROR(ENOMEM);
        }
        memcpy(h264_data->extradata + h264_data->extradata_size, p2, len + 1);
        h264_data->extradata_size += len;

        av_freep(&sprop);
        ret = 0;
    } else {
        av_log(s, AV_LOG_DEBUG, "Ignoring unknown attribute %s\n", attr);
        return 0;
    }

    return 0;
}

int parse_fmtp_config_h264(AVFormatContext *s, AVStream *stream, PayloadContext *h264_data, const char *attr, const char *value) {
