int parse_h264_fmtp_config(AVFormatContext *s, AVStream *stream, PayloadContext *h264_data, const char *attr, const char *value) {
    if (!strcmp(attr, "packetization-mode")) {
        int mode = strtol(value, NULL, 10);
        if (mode != 0 && mode != 1) {
            av_log(s, AV_LOG_ERROR, "Unsupported H.264 packetization mode: %d\n", mode);
            return AVERROR(EINVAL);
        }
        h264_data->packetization_mode = mode;
        av_log(s, AV_LOG_DEBUG, "H.264 packetization mode set to %d\n", mode);
    } else if (!strcmp(attr, "profile-level-id")) {
        if (strlen(value) != 6) {
            av_log(s, AV_LOG_ERROR, "Invalid profile-level-id length\n");
            return AVERROR(EINVAL);
        }
        memcpy(h264_data->profile_level_id, value, 6);
    } else if (!strcmp(attr, "sprop-parameter-sets")) {
        if (!value || !*value) {
            av_log(s, AV_LOG_ERROR, "Invalid sprop-parameter-sets value\n");
            return AVERROR(EINVAL);
        }
        av_freep(&h264_data->extradata);
        if (av_parser_parse2(NULL, NULL, NULL, NULL, 0, 0, 0, 0, AV_PARSER_PTS_UNKNOWN) < 0) {
            av_log(s, AV_LOG_ERROR, "Failed to parse sprop-parameter-sets\n");
            return AVERROR(EINVAL);
        }
        av_log(s, AV_LOG_DEBUG, "H.264 sprop-parameter-sets parsed successfully\n");
    } else {
        av_log(s, AV_LOG_WARNING, "Unknown H.264 FMTP attribute: %s\n", attr);
        return AVERROR(EINVAL);
    }
    return 0;
}
